function readText(relativePath) {
  return readFileSync(join(repoRoot, relativePath), 'utf8');
}

function readJson(relativePath) {
  return JSON.parse(readText(relativePath));
}

function writeGenerated(relativePath, content) {
  const filePath = join(docsRoot, relativePath);
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, `${generatedNotice}\n\n${content.trim()}\n`);
}

function writePublic(relativePath, content) {
  const filePath = join(publicRoot, relativePath);
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, `${content.trim()}\n`);
}

function docsLink(path) {
  const cleanPath = path.replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '');
  return `/${cleanPath}`;
}

function markdownLink(title, path) {
  return `[${title}](${docsLink(path)})`;
}

function escapeTableCell(value) {
  return String(value ?? '')
    .replaceAll('|', '\\|')
    .replaceAll('\n', '<br>');
}

function formatPackageMap(map) {
  if (!map || Object.keys(map).length === 0) {
    return '_None._';
  }

  return Object.entries(map)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, version]) => `- \`${name}\`: \`${version}\``)
    .join('\n');
}

function formatExportTarget(target) {
  if (typeof target === 'string') {
    return target;
  }

  if (!target || typeof target !== 'object') {
    return '';
  }

  const parts = [];
  if (target.import) {
    parts.push(`import: \`${target.import}\``);
  }
  if (target.require) {
    parts.push(`require: \`${target.require}\``);
  }
  if (target.types) {
    parts.push(`types: \`${target.types}\``);
  }

  return parts.join('<br>');
}

function listJsonFiles(relativeDir) {
  const root = join(repoRoot, relativeDir);
  if (!existsSync(root)) {
    return [];
  }

  return readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
    .map((entry) => join(relativeDir, entry.name))
    .sort();
}

function listFixtureFiles() {
  const fixturesRoot = join(docsRoot, 'fixtures');
  if (!existsSync(fixturesRoot)) {
    return [];
  }

  const files = [];
  const visit = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const fullPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        visit(fullPath);
      } else if (entry.isFile() && entry.name.endsWith('.json')) {
        files.push(relative(docsRoot, fullPath));
      }
    }
  };

  visit(fixturesRoot);
  return files.sort();
}

function generateComparisonPage() {
  const comparison = readText('COMPARISON.md')
    .replaceAll('../COMPARISON.md', 'comparison.md')
    .replaceAll('../../COMPARISON.md', '../comparison.md');
  writeGenerated('comparison.md', comparison);
}

