function generatePackageReference() {
  const pkg = readJson('packages/vite-plugin-federation/package.json');
  const exportRows = Object.entries(pkg.exports ?? {})
    .map(
      ([exportName, target]) =>
        `| \`${escapeTableCell(exportName)}\` | ${escapeTableCell(formatExportTarget(target))} |`,
    )
    .join('\n');

  const scriptRows = Object.entries(pkg.scripts ?? {})
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, command]) => `| \`${name}\` | \`${escapeTableCell(command)}\` |`)
    .join('\n');

  writeGenerated(
    'reference/package.md',
    `# Package Metadata

Generated from \`packages/vite-plugin-federation/package.json\`.

## Overview

| Field | Value |
| ----- | ----- |
| Name | \`${pkg.name}\` |
| Version | \`${pkg.version}\` |
| Description | ${escapeTableCell(pkg.description)} |
| License | \`${pkg.license}\` |
| Node | \`${pkg.engines?.node ?? ''}\` |

## Public Exports

| Export | Target |
| ------ | ------ |
${exportRows}

## Peer Dependencies

${formatPackageMap(pkg.peerDependencies)}

## Runtime Dependencies

${formatPackageMap(pkg.dependencies)}

## Package Scripts

| Script | Command |
| ------ | ------- |
${scriptRows}`,
  );
}

function inferExampleRole(name, relativePath) {
  const key = `${name} ${relativePath}`.toLowerCase();
  const directoryName = basename(dirname(relativePath)).toLowerCase();
  if (key.includes('webpack')) {
    return 'Webpack compatibility remote';
  }
  if (key.includes('ssr')) {
    return 'SSR host';
  }
  if (directoryName.endsWith('-host') || directoryName.endsWith('-hosts')) {
    return 'Host';
  }
  if (directoryName.endsWith('-remote') || directoryName.endsWith('-remotes')) {
    return 'Remote';
  }
  if (key.includes('shared') || key.includes('dep') || key.includes('lib')) {
    return 'Shared package';
  }
  if (key.includes('host')) {
    return 'Host';
  }
  if (key.includes('remote')) {
    return 'Remote';
  }
  return 'Example';
}

function listExamplePackages() {
  const examplesRoot = join(repoRoot, 'examples');
  if (!existsSync(examplesRoot)) {
    return [];
  }

  return readdirSync(examplesRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => {
      const relativePackagePath = join('examples', entry.name, 'package.json');
      const absolutePackagePath = join(repoRoot, relativePackagePath);
      if (!existsSync(absolutePackagePath)) {
        return null;
      }

      const pkg = readJson(relativePackagePath);
      return {
        name: pkg.name ?? entry.name,
        path: dirname(relativePackagePath),
        role: inferExampleRole(pkg.name ?? entry.name, relativePackagePath),
        scripts: Object.keys(pkg.scripts ?? {}).sort(),
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.path.localeCompare(b.path));
}

function generateExamplesReference() {
  const rows = listExamplePackages()
    .map((example) => {
      const scripts =
        example.scripts.length > 0
          ? example.scripts.map((name) => `\`${name}\``).join(', ')
          : '_None_';
      return `| \`${escapeTableCell(example.name)}\` | \`${example.path}\` | ${example.role} | ${scripts} |`;
    })
    .join('\n');

  writeGenerated(
    'reference/examples.md',
    `# Examples

Generated from \`examples/*/package.json\`.

| Package | Path | Role | Scripts |
| ------- | ---- | ---- | ------- |
${rows}`,
  );
}

function generateSchemaReference() {
  const schemaRows = listJsonFiles('docs/schemas')
    .map((relativePath) => {
      const schema = readJson(relativePath);
      const name = basename(relativePath);
      const required = Array.isArray(schema.required) ? schema.required.join(', ') : '';
      return `| [${name}](/schemas/${name}) | \`${schema.$id ?? ''}\` | ${escapeTableCell(required)} |`;
    })
    .join('\n');

  const fixtureRows = listFixtureFiles()
    .map((relativePath) => {
      const publicPath = relativePath.replace(/^fixtures\//, '/fixtures/');
      return `| [${relativePath}](${publicPath}) |`;
    })
    .join('\n');

  writeGenerated(
    'reference/schemas.md',
    `# Schemas And Fixtures

Generated from \`docs/schemas/*.json\` and \`docs/fixtures/**/*.json\`.

## JSON Schemas

| Schema | \`$id\` | Required Fields |
| ------ | ------ | --------------- |
${schemaRows}

## Compatibility Fixtures

| Fixture |
| ------- |
${fixtureRows}`,
  );
}

function copyPublicJsonAssets() {
  for (const [source, target] of [
    [join(docsRoot, 'schemas'), join(publicRoot, 'schemas')],
    [join(docsRoot, 'fixtures'), join(publicRoot, 'fixtures')],
  ]) {
    rmSync(target, { recursive: true, force: true });
    if (existsSync(source)) {
      mkdirSync(dirname(target), { recursive: true });
      cpSync(source, target, { recursive: true });
    }
  }
}

function generateLlmFiles() {
  const allPages = [...docsCatalog, ...generatedReferencePages];
  const pageList = allPages
    .map((page) => `- ${page.title}: ${docsLink(page.path)} - ${page.description}`)
    .join('\n');

  writeGenerated(
    'llms.md',
    `# LLM Documentation

Use these generated files when a coding agent needs compact repository context:

- [llms.txt](/llms.txt): short documentation map.
- [llms-full.txt](/llms-full.txt): expanded repository documentation snapshot.

The files are regenerated by \`pnpm docs:generate\` and included in the GitHub Pages build.`,
  );

  writePublic(
    'llms.txt',
    `# vite-plugin-federation

> Production-grade Module Federation for Vite hosts, remotes, SSR, and manifest-first runtime loading.

Repository: ${repoUrl}
npm: https://www.npmjs.com/package/${packageName}

## Documentation

${pageList}

## Recommended Imports

\`\`\`ts
import federation from "vite-plugin-federation";
import { loadRemoteFromManifest } from "vite-plugin-federation/runtime";
\`\`\``,
  );

  const expandedSources = [
    { title: 'Root README', path: 'README.md' },
    { title: 'Package README', path: 'packages/vite-plugin-federation/README.md' },
    { title: 'Plugin Comparison', path: 'COMPARISON.md' },
    ...docsCatalog
      .filter((page) => existsSync(join(docsRoot, page.path)))
      .map((page) => ({ title: page.title, path: `docs/${page.path}` })),
  ];

  const expandedContent = expandedSources
    .map((source) => {
      const content = readText(source.path).trim();
      return `# ${source.title}\n\nSource: ${source.path}\n\n${content}`;
    })
    .join('\n\n---\n\n');

  writePublic(
    'llms-full.txt',
    `# vite-plugin-federation Full Documentation Snapshot

Generated from checked-in repository docs. Prefer source files for edits.

${expandedContent}`,
  );
}

